    sse_encode_u_32(self.calendarWeek, serializer);
    sse_encode_String(self.opponent, serializer);
    sse_encode_u_8(self.oppStrength, serializer);
    sse_encode_bool(self.isHome, serializer);
    sse_encode_bool(self.played, serializer);
    sse_encode_String(self.date, serializer);
  }
}
